import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, waitFor, within } from "storybook/test";
import { ComponentProps, useState } from "react";
import { VoucherForm } from "./voucher-form";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Voucher Form",
  component: VoucherForm,
  parameters: {
    docs: {
      description: {
        component:
          "Form for applying a discount code: one required code field plus cancel and submit buttons. The typed " +
          "value is trimmed and upper-cased as you type. Submitting (button or Enter) calls `onSubmit(code)` when " +
          "the field has a value; an empty submit shows the required message instead, which otherwise appears " +
          "three seconds after the field was emptied. When the parent passes `error` the field is replaced by a " +
          "critical banner, which also repeats the code entered in this form when there is one, and the submit " +
          'button turns into "Använd annan kod", which calls `onRemoveCodeErrorCode` so the parent can clear the ' +
          "error (`isRemovingVoucher` swaps its label for a spinner meanwhile). `disabled` locks the field and " +
          "the submit button while a request is pending.",
      },
    },
  },
  argTypes: {
    onSubmit: { table: { disable: true } },
    onRemoveCodeErrorCode: { table: { disable: true } },
    onCancel: { table: { disable: true } },
  },
  args: {
    disabled: false,
    isRemovingVoucher: false,
    onSubmit: fn(),
    onRemoveCodeErrorCode: fn(),
    onCancel: fn(),
  },
} satisfies Meta<typeof VoucherForm>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

const voucherError = {
  heading: "Rabattkoden kunde inte användas",
  paragraph: "Koden gäller inte för produkterna i din varukorg.",
};

/** The parent rejected the code: the field is replaced by a banner and the submit button offers to try another code. */
export const WithError: Story = {
  args: { error: voucherError },
};

/**
 * Stands in for the parent, which only knows about an error once a code has been submitted. The entered code is
 * the form's own state, so the banner can repeat it only when the form stays mounted across the rejection -
 * hence a wrapper rather than an `error` arg. The error itself still comes from the args, so the control works.
 */
const VoucherFormWithRejectingParent = ({ error, ...props }: ComponentProps<typeof VoucherForm>) => {
  const [isRejected, setIsRejected] = useState(false);
  return (
    <VoucherForm
      {...props}
      error={isRejected ? error : undefined}
      onSubmit={(voucherCode) => {
        setIsRejected(true);
        props.onSubmit(voucherCode);
      }}
      onRemoveCodeErrorCode={() => {
        setIsRejected(false);
        props.onRemoveCodeErrorCode();
      }}
    />
  );
};

/** The banner repeats the submitted code, which `WithError` cannot show because nothing was typed there. */
export const ErrorWithSubmittedCode: Story = {
  args: { error: voucherError },
  render: (args) => <VoucherFormWithRejectingParent {...args} />,
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // The required marker is an inline span, so the accessible name is "Rabattkod(Obligatoriskt)".
    await userEvent.type(canvas.getByRole("textbox", { name: /^Rabattkod/ }), " sommar2026 ");
    await userEvent.click(canvas.getByRole("button", { name: "Använd rabattkod" }));
    // The banner animates in via framer-motion, so retry until the repeated code is visible.
    await waitFor(() => expect(canvas.getByText("SOMMAR2026")).toBeVisible());
    await expect(canvas.getByRole("button", { name: "Använd annan kod" })).toBeVisible();
  },
};

export const VariantStates: Story = {
  parameters: showcaseParameters,
  // No code is entered here, so the banners show heading and paragraph only - see ErrorWithSubmittedCode for
  // the repeated code. The spinner shows as a dot: Chromatic captures its last frame, which draws almost
  // no stroke.
  render: (args) => (
    <ShowcaseLayout title="Form states (disabled, error, removing)" variantType="state">
      <Variant label="disabled (request pending)">
        <VoucherForm {...args} disabled />
      </Variant>
      <Variant label="error">
        <VoucherForm {...args} error={voucherError} />
      </Variant>
      <Variant label="error + isRemovingVoucher (spinner in the button)">
        <VoucherForm {...args} error={voucherError} isRemovingVoucher />
      </Variant>
    </ShowcaseLayout>
  ),
};

/** Submitting with an empty field shows the required message right away, without waiting for the debounce. */
export const RequiredError: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByRole("button", { name: "Använd rabattkod" }));
    // The error animates in via framer-motion, so retry until visible.
    await waitFor(() => expect(canvas.getByText("Vänligen ange ett värde")).toBeVisible());
  },
};

const onSubmitSpy = fn();

export const TestSubmit: Story = {
  args: { onSubmit: onSubmitSpy },
  // Behaviour only: the code is upper-cased and trimmed before it reaches onSubmit.
  play: async ({ canvasElement }) => {
    onSubmitSpy.mockClear();
    const canvas = within(canvasElement);
    // The required marker is an inline span, so the accessible name is "Rabattkod(Obligatoriskt)".
    const input = canvas.getByRole("textbox", { name: /^Rabattkod/ });
    await userEvent.type(input, " sommar2026 ");
    await expect(input).toHaveValue("SOMMAR2026");
    await userEvent.click(canvas.getByRole("button", { name: "Använd rabattkod" }));
    await expect(onSubmitSpy).toHaveBeenCalledTimes(1);
    await expect(onSubmitSpy).toHaveBeenCalledWith("SOMMAR2026");
  },
};
