import { InputField } from "@/core/components/primitives/input-field/input-field";
import { useTranslation } from "react-i18next";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import styles from "./voucher-form.module.less";
import { debounce, toUpper } from "lodash-es";
import { useMemo, useState } from "react";
import { LabelKey } from "@/core/labels/i18n";
import { Banner, BannerProps } from "@/core/components/primitives/banner/banner";
import { Icon } from "@/core/components/primitives/icon/icon";

type VoucherFormProps = {
  /** Callback function triggered when the form is submitted with a valid voucher code */
  onSubmit: (voucherCode: string) => void;
  /** Callback function to clear/remove the current error state, if any */
  onRemoveCodeErrorCode: () => void;
  /** Optional callback function triggered when the cancel button is clicked */
  onCancel?: () => void;
  /** Whether the form inputs and submit button should be disabled. Usually when a API-call is pending */
  disabled?: boolean;
  /** Whether a voucher removal operation is in progress (shows loading state) */
  isRemovingVoucher?: boolean;
  /**
   * Error from the parent. Replaces the field with a critical banner carrying this heading and paragraph,
   * followed by the code currently entered in the field when there is one.
   */
  error?: Pick<BannerProps, "heading" | "paragraph">;
};

const checkCode = (value: string): undefined | LabelKey => {
  if (!value) {
    return "inputValidationRequired";
  }
  return undefined;
};

export const VoucherForm = ({
  onSubmit,
  onRemoveCodeErrorCode,
  onCancel,
  disabled,
  isRemovingVoucher,
  error: bannerError,
}: VoucherFormProps) => {
  const { t } = useTranslation();

  const [code, setCode] = useState<string>();
  const [codeErrorText, setCodeErrorText] = useState<LabelKey>();

  const checkCodeOnDebounce = useMemo(
    () => debounce((newValue: string) => setCodeErrorText(checkCode(newValue)), 3_000),
    [],
  );

  const submit = () => {
    if (disabled) return;

    // recheck for errors, in case debounce hasn't run yet
    const instantCodeErrorText = checkCode(code ?? "");

    setCodeErrorText(instantCodeErrorText);

    if (!instantCodeErrorText && code) {
      onSubmit(code.trim());
    }
  };

  return (
    <div className={styles.formWrapper}>
      {bannerError && (
        <Banner type="critical" border heading={bannerError.heading} role="alert">
          <>
            {bannerError.paragraph}
            {code && (
              <div className={styles.discountBannerError}>
                <Icon name="discount" />
                {code}
              </div>
            )}
          </>
        </Banner>
      )}

      {!bannerError && (
        <div>
          <InputField
            name="code"
            label={t("voucherCode")}
            isRequired
            value={code}
            onChange={(_name, value) => {
              checkCodeOnDebounce(toUpper(value.trim()));
              setCode(toUpper(value.trim()));
            }}
            isValid={!codeErrorText}
            disabled={disabled}
            onKeyDown={(e) => {
              if (e.key === "Enter") submit();
            }}
            errorText={codeErrorText && t(codeErrorText)}
          />
        </div>
      )}

      <div className={styles.buttonRow}>
        <OutlineButton size="medium" label={t("cancel")} isFullWidth onClick={() => onCancel?.()} />
        {!bannerError && (
          <PrimaryButton
            size="medium"
            label={t("applyVoucherCode")}
            isDisabled={disabled}
            isFullWidth
            onClick={submit}
          />
        )}
        {bannerError && (
          <PrimaryButton
            size="medium"
            label={isRemovingVoucher ? undefined : t("useOtherVoucherCode")}
            isFullWidth
            iconCenterNew={isRemovingVoucher ? "loading" : undefined}
            onClick={() => {
              onRemoveCodeErrorCode();
            }}
          />
        )}
      </div>
    </div>
  );
};
